import {vikingCollapse} from './VikingBoard';

/** English game help: remove all of one regular type, transform all of another
 * regular type to another symbol. Target type is explicit: the translated
 * operator PDF ties it to removedType but the English help does not. Until
 * observed, the caller must supply a researched plan rather than assume one.
 * This function executes the effect; it does not roll its probability. */
export function vikingLoki(
 board:readonly number[],removedType:number,transformedType:number,targetType:number,
 refill:(column:number,row:number)=>number,
){
 for(const symbol of [removedType,transformedType,targetType])if(!Number.isInteger(symbol)||symbol<0||symbol>8)throw Error('Loki selects regular symbols only');
 if(removedType===transformedType||transformedType===targetType)throw Error('Loki requires distinct source types and an actual transformation');
 if(board.length!==49||board.some(s=>!Number.isInteger(s)||s<0||s>12))throw Error('Invalid Loki board');
 if(!board.includes(removedType)||!board.includes(transformedType))throw Error('Loki selected type absent from board');
 const before=[...board];
 // Determine both sets from BEFORE. Newly converted symbols must not be
 // accidentally erased when their target happens to be the removed type.
 const removed=before.flatMap((symbol,cell)=>symbol===removedType?[cell]:[]);
 const changed=before.flatMap((symbol,cell)=>symbol===transformedType?[{cell,from:symbol,to:targetType}]:[]);
 const transformed=before.map(symbol=>symbol===transformedType?targetType:symbol);
 const result=vikingCollapse(transformed,removed,refill);
 return {kind:'loki' as const,before,removed,changed,transformed,...result};
}
