import {native} from 'cc';

export async function androidGoogleIdToken():Promise<string>{
 const id='google-'+Date.now().toString(36);
 const invoke=(method:string)=>native.reflection.callStaticMethod('com/cocos/game/PocketGoogleSignIn',method,'(Ljava/lang/String;)Ljava/lang/String;',id) as string;
 try{
  if(invoke('signIn')!=='waiting')throw Error('Google 로그인을 시작하지 못했습니다.');
  const started=Date.now();
  while(Date.now()-started<180000){
   await new Promise(resolve=>setTimeout(resolve,200));
   const raw=invoke('poll');if(raw==='waiting')continue;
   if(raw==='failed')throw Error('Google 로그인을 완료하지 못했습니다.');
   const result=JSON.parse(raw);if(result.idToken)return result.idToken;
   throw Error(result.error||'Google 로그인을 완료하지 못했습니다.');
  }
  throw Error('Google 로그인 시간이 초과되었습니다. 다시 시도해 주세요.');
 }finally{invoke('cancel');}
}
