/** A bought bonus can round a small winning stage down to zero coins. Its
 * matched cells must still disappear so later drops and features can play. */
export function cascadeHasMatch(stage:Cascade){return stage.wins.some(win=>win.cells.length>0)||!!stage.removedCells?.length;}
