import type {SpinResult,Win} from './SlotMain';
export const KITTEN_ART=['rank_10','rank_j','rank_q','rank_k','rank_a','attic_cat','scratching_post','water_bowl','toy_mouse','milk_bottle','cat_bed','golden_paw','green_yarn','red_yarn','blue_yarn'];
export const kittenSymbol=(name:string)=>'caesar-cat-palace-'+name;
export type KittenEvent=
 |{kind:'green';set:number;cell:number;before:number;after:number;award:Win}
 |{kind:'red';set:number;cell:number;beforeSets:number;afterBoards:string[][]}
 |{kind:'blue';set:number;cell:number;before:number;after:number;added:4};
export interface KittenStage {beforeBoards:string[][];boards:string[][];wins:Win[][];remainingBefore:number;remainingAfterConsume:number;remainingAfter:number;events:KittenEvent[]}
export interface KittenPlayback {initialBoards:string[][];stages:KittenStage[];finalBoards:string[][];bank:number;collection:Win[]}
export interface KittenTurn {boards:string[][];wins:Win[][];green?:{set:number;cell:number;amount:number};red?:{set:number;cell:number;newBoards:string[][]};blue?:{set:number;cell:number}}
/** Explicit replay inputs keep the unverified 50-line paytable and natural yarn
 * distribution out of the feature reducer. Yarn effects use separate events. */
export function kittenSequence(initialBoards:string[][],turns:KittenTurn[],bet:number):SpinResult{
 let boards=initialBoards.map(board=>[...board]),remaining=0,bank=0;const stages:KittenStage[]=[],wins:Win[]=[];
 const validate=(items:string[][])=>{if(!items.length||items.some(board=>board.length!==15))throw Error('Invalid Kitten reel set');};validate(boards);
 if(!Number.isSafeInteger(bet)||bet<1||!turns.length)throw Error('Invalid Kitten sequence');
 const checkYarn=(input:{set:number;cell:number},kind:string)=>{if(!Number.isInteger(input.set)||input.set<0||input.set>=boards.length||!Number.isInteger(input.cell)||input.cell<0||input.cell>=15||boards[input.set][input.cell]!==kittenSymbol(kind+'_yarn'))throw Error('Kitten yarn ownership mismatch');};
 for(const [index,turn]of turns.entries()){
  if(index>0&&remaining===0)throw Error('Kitten respins have already ended');validate(turn.boards);
  if(turn.boards.length!==boards.length||turn.wins.length!==boards.length)throw Error('Kitten set count mismatch');
  const beforeBoards=boards.map(board=>[...board]),remainingBefore=remaining,remainingAfterConsume=Math.max(0,remaining-1);remaining=remainingAfterConsume;
  boards=turn.boards.map(board=>[...board]);const landed=boards.map(board=>[...board]),roundWins=turn.wins.map(set=>set.map(win=>({...win,cells:[...win.cells]}))),events:KittenEvent[]=[];
  for(const set of roundWins)for(const win of set){if(!Number.isSafeInteger(win.amount)||win.amount<0||win.cells.some(cell=>!Number.isInteger(cell)||cell<0||cell>=15))throw Error('Invalid Kitten line award');wins.push(win);}
  if(turn.green){checkYarn(turn.green,'green');const before=bank,amount=turn.green.amount;if(!Number.isSafeInteger(amount)||amount<1)throw Error('Invalid green prize');bank+=amount;const award:Win={line:-1,symbol:kittenSymbol('green_yarn'),amount,cells:[turn.green.cell]};events.push({kind:'green',set:turn.green.set,cell:turn.green.cell,before,after:bank,award});wins.push(award);}
  if(turn.red){checkYarn(turn.red,'red');validate(turn.red.newBoards);if(turn.red.newBoards.length!==boards.length)throw Error('Red yarn must double the reel sets');events.push({kind:'red',set:turn.red.set,cell:turn.red.cell,beforeSets:boards.length,afterBoards:[...boards,...turn.red.newBoards].map(board=>[...board])});}
  if(turn.blue){checkYarn(turn.blue,'blue');const before=remaining;remaining+=4;events.push({kind:'blue',set:turn.blue.set,cell:turn.blue.cell,before,after:remaining,added:4});}
  for(const event of events){boards[event.set][event.cell]=kittenSymbol('rank_10');if(event.kind==='red'){boards.push(...event.afterBoards.slice(event.beforeSets).map(board=>[...board]));event.afterBoards=boards.map(board=>[...board]);}}
  stages.push({beforeBoards,boards:landed,wins:roundWins,remainingBefore,remainingAfterConsume,remainingAfter:remaining,events});
 }
 if(remaining!==0)throw Error('Kitten sequence ended before granted respins');
  const collection=stages.flatMap(stage=>stage.events.flatMap(event=>event.kind==='green'?[event.award]:[]));
  return {bet,board:[...boards[0]],wins,payout:wins.reduce((sum,win)=>sum+win.amount,0),kittenFeature:{initialBoards:initialBoards.map(board=>[...board]),stages,finalBoards:boards.map(board=>[...board]),bank,collection}};
}
