// One shared silhouette, with colors applied by the renderer (no variant PNGs).
export const voxelCostumes = [
 {id:'voxel-hair-sand',slot:'hair' as const,name:'샌드 헤어',color:'#bd915d',price:0,tag:'기본 색상'},
 {id:'voxel-hair-slate',slot:'hair' as const,name:'슬레이트 헤어',color:'#677889',price:0,tag:'기본 색상'},
 {id:'voxel-top-sage',slot:'top' as const,name:'세이지 반팔',color:'#8bac95',price:0,tag:'기본 색상'},
 {id:'voxel-top-rust',slot:'top' as const,name:'러스트 반팔',color:'#bd7860',price:0,tag:'기본 색상'},
 {id:'voxel-pants-charcoal',slot:'pants' as const,name:'차콜 반바지',color:'#505766',price:0,tag:'기본 색상'},
 {id:'voxel-pants-khaki',slot:'pants' as const,name:'카키 반바지',color:'#999377',price:0,tag:'기본 색상'},
];
export const voxelParts=['body','hair','top','pants','shoes'] as const;
export const voxelDefaults:Record<string,string>={hair:'basic-hair',top:'night',pants:'basic-shorts'};
export function supportsVoxel(equipment:Partial<Record<string,string>>,onlySlot?:string){
 const supported=(slot:string,id?:string)=>id===undefined||id===voxelDefaults[slot]||voxelCostumes.some(c=>c.slot===slot&&c.id===id);
 if(onlySlot)return ['hair','top','pants'].includes(onlySlot)&&supported(onlySlot,equipment[onlySlot]);
 return ['hair','top','pants'].every(slot=>supported(slot,equipment[slot]))&&
  ['hat','glasses','earrings','necklace','jacket','shoes'].every(slot=>!equipment[slot]);
}
