import {GladiatorMode,GladiatorState,GladiatorDuel,GladiatorCoin,GladiatorEvent,GladiatorPlayback,gladiatorCopy,gladiatorStart,gladiatorSymbol} from './GladiatorFeature';

export const GLADIATOR_ARENA_VALUES=[1,2,3,4,5,10,15,20,25,50,75,100,150,200,250,500,1000];
export const GLADIATOR_BEAST_VALUES=GLADIATOR_ARENA_VALUES.slice(0,-1);
export const GLADIATOR_CENTRE_VALUES=[2,3,4,5,10,15,20];
export const GLADIATOR_COIN_VALUES=[2,3,4,5,10];
export function gladiatorBonusStart(mode:GladiatorMode){const state=gladiatorStart(mode);if(mode==='arena')state.reels.fill(1);return state;}
/** Source help: bonus duels are NOT wild/payline wins. Coins precede duels;
 * Arena replaces the reel bank, Beast accumulates current winners. Only the
 * terminal bank sum is awarded, sharing its Win with the result for scaling. */
export function gladiatorBonusResolve(state:GladiatorState,duels:GladiatorDuel[],coins:GladiatorCoin[],bet:number,budget=bet*10000):GladiatorPlayback{
 if(!Number.isInteger(state.lives)||state.lives<1||state.lives>3||state.reels.length!==5||state.unlocked.length!==5||state.reels.some(n=>!Number.isSafeInteger(n)||n<0)||!Number.isSafeInteger(bet)||bet<1||!Number.isSafeInteger(budget)||budget<0||budget>bet*10000)throw Error('Invalid Gladiator bonus state');
 const reelSet=new Set<number>(),coinCells=new Set<number>();
 for(const duel of duels){
  if(!Number.isInteger(duel.reel)||duel.reel<0||duel.reel>4||reelSet.has(duel.reel)||!['left','right'].includes(duel.winner)||![duel.left,duel.right].every(n=>Number.isSafeInteger(n)&&n>=0))throw Error('Invalid Gladiator duel');
  if(state.mode==='beast'&&duel.reel===2&&!state.unlocked[2])throw Error('Beast reel cannot spin before it is unlocked');
  reelSet.add(duel.reel);
 }
 for(const coin of coins){
  if(state.mode!=='arena'||!Number.isInteger(coin.cell)||coin.cell<0||coin.cell>=20||coinCells.has(coin.cell)||reelSet.has(coin.cell%5)||!GLADIATOR_COIN_VALUES.includes(coin.factor))throw Error('Invalid or conflicting Gladiator coin');coinCells.add(coin.cell);
 }
 const before=gladiatorCopy(state),afterConsume=gladiatorCopy(state);afterConsume.lives--;afterConsume.played++;
 const current=gladiatorCopy(afterConsume),events:GladiatorEvent[]=[],expanded:number[]=[];
 const values=()=>current.reels.map((value,reel)=>state.mode==='beast'&&reel===2?0:value);
 const capped=()=>values().reduce((a,b)=>a+b,0)*bet>=budget;
 for(const coin of coins){
  const previous=gladiatorCopy(current),targets=(coin.epic?[0,1,2,3,4]:[coin.cell%5]).filter(reel=>current.reels[reel]>0);
  targets.forEach(reel=>current.reels[reel]*=coin.factor);
  events.push({kind:'coin',coin:{...coin},targets,before:previous,after:gladiatorCopy(current)});if(capped())break;
 }
 // Centre applies to this spin's outer duels, not stored previous banks.
 const centre=duels.find(duel=>duel.reel===2),beastMultiplier=state.mode==='beast'&&centre?centre[centre.winner]:1;
 const ordered=state.mode==='beast'?[...duels.filter(d=>d.reel===2),...duels.filter(d=>d.reel!==2)]:duels;
 if(!capped())for(const duel of ordered){
  const previous=gladiatorCopy(current),shown={...duel};
  if(state.mode==='arena'){
   // Coins (including an Epic on another reel) can change the current top
   // combatant before this duel resolves. Winner identity stays deterministic.
   shown.left=current.reels[duel.reel];current.reels[duel.reel]=shown[shown.winner];
  }else if(duel.reel===2)current.reels[2]=duel[duel.winner];
  else current.reels[duel.reel]+=duel[duel.winner]*beastMultiplier;
  if(!Number.isSafeInteger(current.reels[duel.reel]))throw Error('Gladiator multiplier overflow');
  current.unlocked[duel.reel]=true;expanded.push(duel.reel);events.push({kind:'duel',duel:shown,before:previous,after:gladiatorCopy(current)});
  if(capped())break;
 }
 if(state.mode==='beast'&&!current.unlocked[2]&&[0,1,3,4].every(reel=>current.unlocked[reel])){
  const previous=gladiatorCopy(current);current.unlocked[2]=true;events.push({kind:'unlock',before:previous,after:gladiatorCopy(current)});
 }
 const capReached=capped(),added=duels.length&&!capReached?3-current.lives:0;
 current.lives=capReached?0:duels.length?3:current.lives;
 const result:GladiatorPlayback={before,afterConsume,after:gladiatorCopy(current),events,expanded,wins:[],added,payoutMode:'bank'};
 if(current.lives===0){
  const finalValues=values(),rawMultiplier=finalValues.reduce((a,b)=>a+b,0),amount=Math.min(budget,rawMultiplier*bet);
  const award={line:-1,symbol:gladiatorSymbol('duel_swords'),amount,cells:[]};
  result.collection={values:finalValues,rawMultiplier,paidMultiplier:amount/bet,award,capReached};result.wins=[award];
 }
 return result;
}
