import {native,sys} from 'cc';
export type AdOutcome='earned'|'closed'|'failed';
/** Google Mobile Ads native adapter. Web deliberately keeps the labelled simulation. */
export class RewardedAds {
 private pending=false;
 lastError="";
 private captureError(){try{if(sys.os===sys.OS.ANDROID)this.lastError=this.invoke('diagnostic','');}catch{this.lastError='ADS_BRIDGE';}}
 get supported(){return sys.isNative&&(sys.os===sys.OS.ANDROID||sys.os===sys.OS.IOS);}
 get privacyOptionsRequired():boolean{
  if(!sys.isNative||sys.os!==sys.OS.ANDROID)return false;
  try{return this.invoke('privacyStatus','')==='required';}catch{return false;}
 }
 private invoke(method:'show'|'poll'|'cancel'|'privacyStatus'|'privacyOptions'|'privacyPoll'|'diagnostic',id:string):string{
  if(sys.os===sys.OS.ANDROID)return native.reflection.callStaticMethod('com/cocos/game/PocketAds',method,'(Ljava/lang/String;)Ljava/lang/String;',id);
  return native.reflection.callStaticMethod('PocketAds',method+':',id);
 }
 async openPrivacyOptions():Promise<boolean>{
  if(!this.privacyOptionsRequired||this.pending)return false;
  this.pending=true;
  try{
   if(this.invoke('privacyOptions','')!=='showing')return false;
   const started=Date.now();
   while(Date.now()-started<600000){
    await new Promise(resolve=>setTimeout(resolve,200));
    const state=this.invoke('privacyPoll','');
    if(state==='closed')return true;
    if(state!=='showing')return false;
   }
   return false;
  }catch{return false;}finally{this.pending=false;}
 }
 async show():Promise<AdOutcome>{
  if(!this.supported||this.pending)return 'failed';this.lastError='';this.pending=true;
  const id=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
  try{
   if(this.invoke('show',id)!=='loading'){this.captureError();return 'failed';}
   const started=Date.now();let showing=false;
   while(Date.now()-started<(showing?600000:60000)){
    await new Promise(resolve=>setTimeout(resolve,200));const state=this.invoke('poll',id);
    if(state==='earned'||state==='closed'||state==='failed'){if(state==='failed')this.captureError();return state;}
    if(state==='showing')showing=true;
   }
   this.lastError='ADS_TIMEOUT';return 'failed';
  }catch{this.lastError='ADS_BRIDGE';return 'failed';}finally{try{this.invoke('cancel',id);}catch{}this.pending=false;}
 }
}
