import {StargemSlot} from './StargemSlot';
export function stargemAudit(params:URLSearchParams){const slot=new StargemSlot(),outcome=params.get('audit-outcome');if(outcome)slot.demoSpin=bet=>{let seed=409280;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<300000;i++){const r=slot.spin(bet,rng),rounds=r.rounds||[r],f=rounds[0].stargemFeature!,match=outcome==='independent'?!r.rounds&&f.lineWins.length===0&&f.money.length>0:outcome==='shared'?!r.rounds&&f.money.some(m=>f.lineWins.some(w=>w.cells.includes(m.cell))):outcome==='multi-money'?!r.rounds&&f.money.length>=3:outcome==='retrigger'?rounds.some(x=>!!x.freeSpinsAdded):outcome==='bonus'?!!r.rounds:outcome==='no-win'?!r.rounds&&r.wins.length===0:outcome==='single-win'?!r.rounds&&r.wins.length===1:outcome==='multi-win'?!r.rounds&&r.wins.length>1:false;if(match)return r;}throw Error('Stargem natural fixture unavailable');};return slot;}
